<?php }elseif($tab==='permissions'){$perm=db()->prepare('SELECT p.*,COALESCE(ap.allowed,0) allowed FROM permissions p LEFT JOIN agent_permissions ap ON ap.permission_key=p.permission_key AND ap.agent_id=? ORDER BY p.category,p.permission_key');$perm->execute([$aid]);$tools=db()->prepare('SELECT * FROM agent_tools WHERE agent_id=? ORDER BY tool_key');$tools->execute([$aid]);$caps=AgentCapabilityService::catalogForAgent($aid);$projects=db()->prepare("SELECT p.id,p.name,p.primary_domain,COALESCE(apa.access_scope,'') access_scope FROM projects p LEFT JOIN agent_project_access apa ON apa.project_id=p.id AND apa.agent_id=? ORDER BY p.is_system_project DESC,p.name");$projects->execute([$aid]);?><div class="grid"><section class="card span-7"><div class="card-title"><h2>جدول الصلاحيات</h2><span class="muted small">كل وكيل بياخد أقل صلاحيات تكفي شغله، والصلاحيات الحساسة واضحة.</span></div><div class="table-wrap"><table><thead><tr><th>المجموعة</th><th>الصلاحية</th><th>حساسة</th><th>مسموح</th></tr></thead><tbody><?php foreach($perm->fetchAll() as $p):?><tr><td><?=e(AdminUi::label((string)$p['category']))?></td><td><?=e($p['label'])?></td><td><?=$p['dangerous']?'⚠':'—'?></td><td><form method="post" action="action.php" class="inline-form"><?=AdminUi::csrf()?><input type="hidden" name="action" value="agent_permission_toggle"><input type="hidden" name="agent_id" value="<?=$aid?>"><input type="hidden" name="permission_key" value="<?=e($p['permission_key'])?>"><input type="hidden" name="allowed" value="<?=$p['allowed']?0:1?>"><button class="btn <?=$p['allowed']?'secondary':''?> small-btn"><?=$p['allowed']?'مسموح':'منع'?></button></form></td></tr><?php endforeach?></tbody></table></div></section><section class="card span-5"><div class="card-title"><h2>الأدوات</h2></div><?php foreach($tools->fetchAll() as $t):?><div class="mini-item"><div class="grow"><b><?=e(AdminUi::label($t['tool_key']))?></b><small><?=e($t['config_json'] && $t['config_json']!=='{}'?'إعدادات خاصة محفوظة':'بدون إعدادات إضافية')?></small></div><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="agent_tool_toggle"><input type="hidden" name="agent_id" value="<?=$aid?>"><input type="hidden" name="tool_key" value="<?=e($t['tool_key'])?>"><input type="hidden" name="allowed" value="<?=$t['allowed']?0:1?>"><button class="btn secondary small-btn"><?=$t['allowed']?'مفعّل':'موقوف'?></button></form></div><?php endforeach?><form method="post" action="action.php" style="margin-top:15px"><?=AdminUi::csrf()?><input type="hidden" name="action" value="agent_tool_add"><input type="hidden" name="agent_id" value="<?=$aid?>"><div class="field"><label>إضافة أداة</label><input name="tool_key" required placeholder="مثال: تحسين الظهور"></div><button class="btn secondary">إضافة</button></form></section><section class="card span-12"><div class="card-title"><div><h2>القدرات الجاهزة للوكلاء</h2><span class="muted small">يمكن تفعيل Capability كاملة بدون برمجة جديدة؛ التفعيل يربط الأداة والصلاحيات التابعة لها تلقائيًا.</span></div></div><div class="two-col"><?php foreach($caps as $c):?><div class="mini-item"><div class="grow"><b><?=e($c['label_ar'])?></b><small><?=e($c['description_text']?:$c['capability_key'])?></small></div><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="agent_capability_toggle"><input type="hidden" name="agent_id" value="<?=$aid?>"><input type="hidden" name="capability_key" value="<?=e($c['capability_key'])?>"><input type="hidden" name="enabled" value="<?=$c['assigned']?0:1?>"><button class="btn secondary small-btn"><?=$c['assigned']?'مفعّلة':'تفعيل'?></button></form></div><?php endforeach?></div></section><section class="card span-12"><div class="card-title"><h2>الوصول للمشاريع</h2></div><div class="table-wrap"><table><thead><tr><th>المشروع</th><th>الدومين</th><th>الوصول</th></tr></thead><tbody><?php foreach($projects->fetchAll() as $p):?><tr><td><?=e($p['name'])?></td><td class="mono">