['enabled']?'':'(غير مفعلة)'?></td><td><input form="<?=e($fid)?>" type="checkbox" name="can_send_owner" <?=$c['can_send_owner']?'checked':''?>></td><td><input form="<?=e($fid)?>" type="checkbox" name="can_receive_owner" <?=$c['can_receive_owner']?'checked':''?>></td><td><input form="<?=e($fid)?>" type="checkbox" name="can_start" <?=$c['can_start']?'checked':''?>></td><td><input form="<?=e($fid)?>" type="checkbox" name="requires_ramy_approval" <?=$c['requires_ramy_approval']?'checked':''?>></td><td><input form="<?=e($fid)?>" type="checkbox" name="emergency_enabled" <?=$c['emergency_enabled']?'checked':''?>></td><td><input form="<?=e($fid)?>" type="number" name="rate_limit_per_hour" value="<?=e($c['rate_limit_per_hour']??10)?>" min="1" max="100" style="width:70px"></td><td><form id="<?=e($fid)?>" method="post" action="action.php" class="inline-form"><?=AdminUi::csrf()?><input type="hidden" name="action" value="agent_channel_policy"><input type="hidden" name="agent_id" value="<?=$aid?>"><input type="hidden" name="channel_key" value="<?=e($c['channel_key'])?>"><button class="btn secondary small-btn">حفظ</button></form></td></tr><?php endforeach?></tbody></table></div></section><section class="card span-12"><div class="card-title"><h2>صلاحيات التواصل بين الوكلاء</h2></div><div class="two-col"><?php foreach($all as $other):if($other['id']===$aid)continue;$row=null;foreach($relRows as $r)if((int)$r['to_agent_id']===(int)$other['id']){$row=$r;break;}?><form method="post" action="action.php" class="subtle"><?=AdminUi::csrf()?><input type="hidden" name="action" value="agent_relationship"><input type="hidden" name="from_slug" value="<?=e($slug)?>"><input type="hidden" name="to_slug" value="<?=e($other['slug'])?>"><b><?=e($a['display_name'])?> → <?=e($other['display_name'])?></b><div class="check-grid" style="margin-top:10px"><label class="check-row"><input type="checkbox" name="can_message" <?=$row&&$row['can_message']?'checked':''?>> مراسلة</label><label class="check-row"><input type="checkbox" name="can_start" <?=$row&&$row['can_start']?'checked':''?>> يبدأ</label><label class="check-row"><input type="checkbox" name="requires_manager_approval" <?=$row&&$row['requires_manager_approval']?'checked':''?>> يحتاج رامي</label></div><button class="btn secondary small-btn" style="margin-top:10px">حفظ</button></form><?php endforeach?></div></section></div>
